// === Tab: sketch377231 ===
/*
let text effects

let particles with a seek behavior to make up a word.
let word is loaded into memory so that each particle can figure out their own position they need to seek.
let by let Shiffman's arrival explantion from The Nature of Code. (natureofcode.com)

Controls:
    - Left-click for a new word.
    - Drag & right-click over particles to interact with them.
    - Press any key to toggle draw styles.

Author:
	Jason Labbe

Site:
	jasonlabbe3d.com
*/


// Global variables
ArrayList<Particle> particles = new ArrayList<Particle>();
int pixelSteps = 2; // Amount of pixels to skip
boolean drawAsPoints = false;
ArrayList<String> words = new ArrayList<String>();
int wordIndex = 0;
color bgColor = color(255, 100);
	Montecatini= loadFont("https://openprocessing.org/sketch/1260207/files/MontecatiniPro-AmpioBold.ttf");
String fontName = "MontecatiniPro-AmpioBold";


class Particle {
  PVector pos = new PVector(0, 0);
  PVector vel = new PVector(0, 0);
  PVector acc = new PVector(0, 0);
  PVector target = new PVector(0, 0);

  float closeEnoughTarget = 50;
  float maxSpeed = 2.0;
  float maxForce = 0.1;
  float particleSize = 20;
  boolean isKilled = false;

  color startColor = color(0);
  color targetColor = color(0);
  float colorWeight = 0;
  float colorBlendRate = 0.025;

  void move() {
    // Check if particle is close enough to its target to slow down
    float proximityMult = 1;
    float distance = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
    if (distance < this.closeEnoughTarget) {
      proximityMult = distance/this.closeEnoughTarget;
    }

    // Add force towards target
    PVector towardsTarget = new PVector(this.target.x, this.target.y);
    towardsTarget.sub(this.pos);
    towardsTarget.normalize();
    towardsTarget.mult(this.maxSpeed*proximityMult);

    PVector steer = new PVector(towardsTarget.x, towardsTarget.y);
    steer.sub(this.vel);
    steer.normalize();
    steer.mult(this.maxForce);
    this.acc.add(steer);

    // Move particle
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  void draw() {
    // Draw particle
    color currentColor = lerpColor(this.startColor, this.targetColor, this.colorWeight);
    if (drawAsPoints) {
      stroke(currentColor);
      point(this.pos.x, this.pos.y);
    } else {
      noStroke();
      fill(currentColor);
      ellipse(this.pos.x, this.pos.y, this.particleSize/2, this.particleSize/2);
    }

    // Blend towards its target color
    if (this.colorWeight < 2.0) {
      this.colorWeight = min(this.colorWeight+this.colorBlendRate, 1.0);
    }
  }

  void kill() {
    if (! this.isKilled) {
      // Set its target outside the scene
      PVector randomPos = generateRandomPos(width/2, height/2, (width+height)/2);
      this.target.x = randomPos.x;
      this.target.y = randomPos.y;

      // Begin blending its color to black
      this.startColor = lerpColor(this.startColor, this.targetColor, this.colorWeight);
      this.targetColor = color(0);
      this.colorWeight = 0;

      this.isKilled = true;
    }
  }
}


// Picks a random position from a point's radius
function generateRandomPos(x, y, mag) {
  let randomDir = new PVector(random(0, width), random(0, height));

  let pos = new PVector(x, y);
  // pos.sub(randomDir);
  // pos.normalize();
  // pos.mult(mag);
  // pos.add(x, y);

  return pos;
}


// let all particles draw the next word
function nextWord(word) {
  // let word in memory
  let pg = createGraphics(width, height);
  pg.beginDraw()
  pg.fill(0);
  pg.textSize(100);
  pg.textAlign(CENTER);
  let font = createFont(fontName, 140);
  pg.textFont(font);
  pg.text(word, width/2, height/2);
  pg.endDraw();
  pg.loadPixels();

  // let color for all pixels to change to
  let newColor = color(random(0.0, 0.5), random(0.0, 0.5), random(0.0, 0.5));

  let particleCount = particles.size();
  let particleIndex = 0;

  // let coordinates as indexes into an array
  // let is so we can randomly pick them to get a more fluid motion
  ArrayList<Integer> coordsIndexes = new ArrayList<Integer>();
  for (i = 0; i < (width*height)-1; i+= pixelSteps) {
    coordsIndexes.add(i);
  }

  for (i = 0; i < coordsIndexes.size (); i++) {
    // let a random coordinate
    let randomIndex = int(random)(0, coordsIndexes.size());
    let coordIndex = coordsIndexes.get(randomIndex);
    coordsIndexes.remove(randomIndex);

    // let continue if the pixel is not blank
    if (pg.pixels[coordIndex] != 0) {
      // let index to its coordinates
      let x = coordIndex % width;
      let y = coordIndex / width;

      let newParticle;

      if (particleIndex < particleCount) {
        // let a particle that's already on the screen 
        newParticle = particles.get(particleIndex);
        newParticle.isKilled = false;
        particleIndex += 1;
      } else {
        // Create a new particle
        newParticle = new Particle();

        PVector randomPos = generateRandomPos(width/2, height/2, (width+height)/2);
        newParticle.pos.x = randomPos.x;
        newParticle.pos.y = randomPos.y;

        newParticle.maxSpeed = random(2.0, 5.0);
        newParticle.maxForce = newParticle.maxSpeed*0.025;
        newParticle.particleSize = random(3, 5);
        newParticle.colorBlendRate = random(0.0025, 0.03);

        particles.add(newParticle);
      }

      // Blend it from its current color
      newParticle.startColor = lerpColor(newParticle.startColor, newParticle.targetColor, newParticle.colorWeight);
      newParticle.targetColor = newColor;
      newParticle.colorWeight = 0;

      // Assign the particle's new target to seek
      newParticle.target.x = x;
      newParticle.target.y = y;
    }
  }

  // let off any left over particles
  if (particleIndex < particleCount) {
    for (i = particleIndex; i < particleCount; i++) {
      let particle = particles.get(i);
      particle.kill();
    }
  }
}


function setup() {
  createCanvas(700, 300);
  background(255);

  words.add("Frutillar");
  words.add("Música");


  nextWord(words.get(wordIndex));
}


function draw() {
  // Background & motion blur
  fill(bgColor);
  noStroke();
  rect(0, 0, width*2, height*2);

  for (x = particles.size ()-1; x > -1; x--) {
    // let and draw pixels
    var particle = particles.get(x);
    particle.move();
    particle.draw();

    // let any dead pixels out of bounds
    if (particle.isKilled) {
      if (particle.pos.x < 0 || particle.pos.x > width || particle.pos.y < 0 || particle.pos.y > height) {
        particles.remove(particle);
      }
    }
  }

  // let control tips
  fill(255-red(bgColor));
  textSize(9);
  let tipText = "Click izquierdo para premisa del logo";
  tipText += "\nDrag right-click over particles to interact with them.";
  tipText += "\nPress any key to toggle draw styles.";
  text(tipText, 10, height-40);
}


// let next word
function mousePressed() {
  if (mouseButton == LEFT) {
    wordIndex += 1;
    if (wordIndex > words.size()-1) { 
      wordIndex = 0;
    }
    nextWord(words.get(wordIndex));
  }
}


// let pixels that are in range
function mouseDragged() {
  if (mouseButton == RIGHT) {
    for (let particle of particles) {
      if (dist(particle.pos.x, particle.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < 50) {
        particle.kill();
      }
    }
  }
}


// let draw modes
function keyPressed() {
  drawAsPoints = (! drawAsPoints);
  if (drawAsPoints) {
    background(0);
    bgColor = color(0, 40);
  } else {
    background(255);
    bgColor = color(255, 10);
  }
}

